from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        prefix, _, arg = name.partition(":")
        if prefix not in STEPS:
            raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
        if not arg:
            raise ValueError("length is missing after ':'")
        try:
            length = int(arg)
        except ValueError:
            raise ValueError(f"'{arg}' is not a valid integer for {prefix!r}")
        return STEPS[prefix](length)
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

